function contentProfile(profile=PROFILE){assert(Object.hasOwn(CONTENT_PROFILES,profile),'Closed FinFlow content profile required');return CONTENT_PROFILES[profile];}
function categoryFor(profile,id){const selected=contentProfile(profile);assert(selected.ids.includes(id),'Admitted objective required');return selected.categories?.[id]||selected.category;}
function challengesLink({click=false}={}){const matches=[...document.querySelectorAll('a[href="/workshop/challenges"]')].filter(e=>e.textContent.trim()==='View All Exercises');if(matches.length!==1)return false;const link=matches[0];if(!link.getClientRects().length||link.getAttribute('aria-disabled')==='true')return false;if(click)link.click();return true;}
function overviewLink({click=false}={}){const matches=[...document.querySelectorAll('a[href="/workshop-dashboard"]')].filter(e=>e.textContent.trim()==='Overview');if(matches.length!==1)return false;const link=matches[0];if(!link.getClientRects().length||link.getAttribute('aria-disabled')==='true')return false;if(click)link.click();return true;}
function browserCap(profile=PROFILE){return contentProfile(profile).browserCap||400;}
function contentRequestDiagnostic(count,stage,profile=PROFILE){return {code:count>browserCap(profile)?'CONTENT_BROWSER_REQUEST_CAP':'CONTENT_BROWSER_REQUEST_DENIED',stage, browserRequests:count};}
function contentOnlyProvider(){let calls=0;const deny=async()=>{calls++;throw Error('TRAVERSAL_CONTENT_INFERENCE_DENIED');};return {provider:'mock',getActiveProviderInfo:()=>({provider:'mock',model:'content-only-no-inference'}),isAvailable:async()=>true,generateResponse:deny,chatWithTools:deny,get count(){return calls;},async drain(){assert.equal(calls,0,'Content profile must not invoke inference');}};}
function allowedRequest(url,origin,count,profile=PROFILE,method='GET'){try{const u=new URL(url);return count<=browserCap(profile)&&(u.origin===origin||['data:','blob:','about:'].includes(u.protocol))&&(!/\/(chat|progress\/complete|progress\/reset)$/.test(u.pathname)||(profile===ADMIN_ENUM_PROFILE&&method==='POST'&&u.pathname==='/api/workshop/sensitive-info/progress/reset'));}catch{return false;}}
function learnerCard({label,hint,solution,completed}){
 const rows=[...document.querySelectorAll('.obj-name')].filter(e=>e.textContent.trim()===label);if(rows.length!==1)return false;
 const content=rows[0].closest('.obj-content'),card=content?.parentElement;if(!card)return false;
 const texts=[...content.querySelectorAll('button')].map(e=>e.textContent.trim());
 return texts.includes('Hint')===hint&&texts.includes('Solution')===solution&&(!completed||card.querySelector('.status-badge')?.textContent.trim()==='DONE');
}
function closePreviewOnly(){const buttons=[...document.querySelectorAll('button')].filter(e=>e.textContent.trim()==='Close Preview');if(buttons.length>1)throw Error('Ambiguous preview overlay');if(buttons.length)buttons[0].click();}
function previewRetired(){return ![...document.querySelectorAll('button')].some(e=>e.textContent.trim()==='Close Preview');}
function objectivePanelPresent(id){
 const headings=[...document.querySelectorAll('h3')].filter(e=>e.textContent.trim().startsWith('Objectives —'));if(headings.length>1)throw Error('Ambiguous objective panel');if(!headings.length)return false;
 const panel=headings[0].parentElement?.parentElement,rows=panel?.querySelectorAll('[data-objective-id="'+id+'"]');if(!rows||rows.length!==1)throw Error('Wrong objective panel');
 return panel.getClientRects().length>0;
}
function hintModalStep({content,count,advance=false}){
 const dialogs=[...document.querySelectorAll('[role="dialog"][data-help-kind="hint"]')];if(dialogs.length!==1)return false;
 const dialog=dialogs[0],body=dialog.querySelector('[data-testid="objective-help-content"]');if(!body||!body.textContent.includes(content.title))return false;
 const actual=[...body.querySelectorAll('ol > li')].map(e=>e.textContent);const expected=content.hints.slice(0,count);
 if(actual.length!==expected.length||actual.some((text,index)=>text!==expected[index]))return false;
 const next=[...dialog.querySelectorAll('button')].filter(e=>e.textContent.trim()==='Next hint');
 if(count<content.hints.length){if(next.length!==1||next[0].disabled||next[0].getAttribute('aria-disabled')==='true')return false;if(advance)next[0].click();}
 else if(next.length!==0||advance)return false;
 return true;
}
function solutionModalVisible({content,admin=false}){
 const headings=[...document.querySelectorAll('h2')].filter(e=>e.textContent.startsWith(content.title));if(headings.length!==1)return false;
 const modal=admin?headings[0].parentElement?.parentElement?.parentElement:headings[0].parentElement?.parentElement;
 if(!modal||(admin&&![...modal.querySelectorAll('button')].some(e=>e.textContent.trim()==='Close Preview')))return false;
 const normalize=x=>String(x).replace(/\s+/g,' ').trim(),text=normalize(modal.textContent);
 const values=[content.title,content.approach,...(content.hints||[]),...(content.tips||[]),...(content.examples||[]).flatMap(x=>[x.prompt,x.explanation])].filter(x=>typeof x==='string'&&x);
 return values.every(x=>text.includes(normalize(x)));
}
function dashboardCard({title,done,total,time}){
 const headings=[...document.querySelectorAll('h3')].filter(e=>e.textContent.trim()===title);if(headings.length!==1)return false;
 const card=headings[0].parentElement?.parentElement?.parentElement;if(!card||card.querySelectorAll('h3').length!==1)return false;
 const text=card.textContent.replace(/\s+/g,' ').trim();return new RegExp('(?:'+done+'\\s*/\\s*'+total+'|'+done+' of '+total+')').test(text)&&text.includes(time);
}
function admitInitialResponses(init,progress,rows,profile=PROFILE){
 const {ids}=contentProfile(profile);
 assert.equal(init.status,200);assert.equal(progress.status,200);assert.equal(init.body.success,true);assert.equal(progress.body.success,true);
 assert(Array.isArray(init.body.objectives));assert(Array.isArray(progress.body.progress));
 const identities=value=>value.map(x=>({id:x.id,label:x.label}));
 assert.deepEqual(identities(init.body.objectives),identities(progress.body.progress));
 assert.equal(new Set(init.body.objectives.map(x=>x.id)).size,init.body.objectives.length);
 assert.equal(progress.body.total,progress.body.progress.length);assert(progress.body.total>=ids.length);
 assert.equal(progress.body.completedCount,ids.length);assert.deepEqual(progress.body.progress.filter(x=>x.completed===true).map(x=>x.id).sort(),[...ids].sort());
 for(const row of rows){const found=progress.body.progress.filter(x=>x.id===row.objective_id);assert.equal(found.length,1);assert.equal(found[0].label,row.label);assert.equal(found[0].completed,true);}
}
function admitDisabledContent(reply){assert.equal(reply.status,403);assert(reply.body&&typeof reply.body==='object');for(const key of ['hint','solution','content'])assert.equal(Object.hasOwn(reply.body,key),false);}
