 if(profile===ADMIN_ENUM_PROFILE){assert.equal(value.projectionRowsPreserved,false);assert.equal(value.controlledProjectionCount,1);assert.equal(value.judgeCalls,0);assert.equal(value.immutableEvidencePreserved,false);assert.equal(value.immutableEvidenceScope,'Empty content fixture; native immutable reset evidence is separate');}
 assert.equal(value.actualModelProof,false);assert.equal(value.modelCalls,0);assert.equal(value.genuineCredit,0);assert.equal(value.projection,'controlled-existing-completion-shape');
