function assertAdminEnumReset(before,after,owner,sibling,completedAt){assert(before.state.completion.some(x=>String(x.row.user_id)===String(owner)&&x.row.workshop_key!==KEY));assert(before.state.completion.some(x=>String(x.row.user_id)===String(sibling)));assert(before.time.some(x=>String(x.row.user_id)===String(owner)&&x.row.workshop_key!==KEY&&Number(x.row.duration_seconds)>0));assert(before.time.some(x=>String(x.row.user_id)===String(sibling)&&Number(x.row.duration_seconds)>0));const own=x=>String(x.row.user_id)===String(owner),other=x=>!own(x)||x.row.workshop_key!==KEY;assert.deepEqual(after.state.completion.filter(own).filter(x=>x.row.workshop_key===KEY),[]);assert.deepEqual(after.state.completion.filter(other),before.state.completion.filter(other));assert.deepEqual(after.state.lab.filter(x=>String(x.row.user_id)===String(sibling)),before.state.lab.filter(x=>String(x.row.user_id)===String(sibling)));assert(after.state.lab.filter(own).every(x=>x.row.completed===false));assert.deepEqual(after.evidence,before.evidence);const scoped=x=>own(x)&&x.row.workshop_key===KEY,old=before.time.filter(scoped),oldIds=new Set(old.map(x=>String(x.row.id)));assert(old.reduce((n,x)=>n+Number(x.row.duration_seconds),0)>=60);assert.deepEqual(after.time.filter(x=>!scoped(x)),before.time.filter(x=>!scoped(x)));for(const {row}of after.time.filter(scoped)){assert(!oldIds.has(String(row.id)));const start=Date.parse(row.session_start),last=Date.parse(row.last_heartbeat);assert(Number.isFinite(start)&&start>=Date.parse(completedAt)&&last>=start);assert(Number(row.duration_seconds)>=0&&Number(row.duration_seconds)<=Math.ceil((last-start)/1000));}}

